<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/customer.php';
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pass=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)$error='Preencha os dados e use senha com pelo menos 10 caracteres.';else{try{$q=db()->prepare("INSERT INTO reseller_accounts(name,email,password_hash,phone) VALUES(?,?,?,?)");$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$phone?:null]);session_regenerate_id(true);unset($_SESSION['admin_id'],$_SESSION['customer_id']);$_SESSION['reseller_id']=(int)db()->lastInsertId();header('Location: reseller-dashboard.php');exit;}catch(Throwable $e){$error='Não foi possível criar a conta. Verifique se o e-mail já está cadastrado.';}}}
layout_start('Cadastro de revendedor');
?><section class="narrow"><h1>Cadastro de revendedor</h1><p>Crie seu acesso para organizar as placas adquiridas nos marketplaces.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post" class="panel"><?=client_csrf_field()?><label>Nome<input name="name" required></label><label>E-mail<input type="email" name="email" required></label><label>Telefone<input name="phone"></label><label>Senha<input type="password" name="password" minlength="10" required></label><button>Criar acesso</button></form><p><a href="reseller-login.php">Já tenho acesso</a></p></section><?php layout_end();?>